package com.bank.analytics;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TopKFrequentDemo {

    private static final Logger log = Logger.getLogger(TopKFrequentDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        CategoryAnalytics analytics = new CategoryAnalytics();

        // Transaction category codes from the day's feed.
        List<String> categories = List.of(
                "GROCERY", "FUEL", "GROCERY", "DINING", "GROCERY",
                "FUEL", "DINING", "GROCERY", "FUEL", "TRAVEL"
        );

        List<String> top2 = analytics.topKFrequent(categories, 2);
        log.info(() -> "Top 2 categories: " + top2);  // GROCERY(4), FUEL(3)
    }
}

// ─── Would be in service/CategoryAnalytics.java in a real project ───
class CategoryAnalytics {

    private static final Logger log = Logger.getLogger(CategoryAnalytics.class.getName());

    java.util.List<String> topKFrequent(java.util.List<String> elements, int k) {
        // Phase 1: count occurrences.
        java.util.Map<String, Integer> counts = new java.util.HashMap<>();
        for (String e : elements) {
            counts.merge(e, 1, Integer::sum);
        }
        log.fine(() -> "  counts = " + counts);

        // Phase 2: keep top k in a min-heap keyed by frequency.
        java.util.PriorityQueue<java.util.Map.Entry<String, Integer>> heap =
                new java.util.PriorityQueue<>(java.util.Comparator.comparingInt(java.util.Map.Entry::getValue));
        for (var entry : counts.entrySet()) {
            heap.offer(entry);
            if (heap.size() > k) {
                heap.poll();   // drop least frequent of current leaders
            }
        }

        // Extract from heap: smallest-first, so reverse to get highest-first.
        java.util.LinkedList<String> result = new java.util.LinkedList<>();
        while (!heap.isEmpty()) {
            result.addFirst(heap.poll().getKey());
        }
        return result;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
